 if slug in ['cash-account-owner','cash-account-servicer']:out+=src(p)+', P92 and P101, §3.1.1, rendered page 5: bank-to-customer cash reporting supports the servicer reporting and the owner cash-management/reconciliation activities, including reconciliation to a sub-ledger or routing to an adequate customer processing system.\n\n'
 for ti,ri in refs:
  t=DATA['tables'][ti-1];out+='- '+link(p,DOC/'tables'/('tbl-%04d.md'%ti),f'T{ti} row {ri}')+': '+esc(' '.join(t['rows'][ri-1]).strip())+'\n'
 out+='\n## Relationships and reuse\n\n'+(''.join('- '+link(p,rolepath(r),rolemap[r][1])+'.\n' for r in relations) if relations else 'No specific counterpart role is established by these cited definitions.\n')
 if slug in ['participant-bank','main-paying-agent']:out+='\nThe source explicitly says the participant bank acts in a main paying agent role here. This does not make the institution category and functional role universally equivalent.\n'
